import{_ as t,o as a,c as r,au as n,aB as o,aC as i,aD as s,aE as l}from"./chunks/framework.ChGI_eLK.js";import"./chunks/theme.CfmGloal.js";const u=JSON.parse('{"title":"Elemental Combat","description":"","frontmatter":{},"headers":[],"relativePath":"guide/elements/Elemental_Combat.md","filePath":"guide/elements/Elemental Combat.md","lastUpdated":1783337123000}'),h={name:"guide/elements/Elemental_Combat.md"};function m(g,e,d,c,p,f){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="Elemental_Combat" tabindex="-1">Elemental Combat <a class="header-anchor" href="#Elemental_Combat" aria-label="Permalink to “Elemental Combat”">​</a></h1><p>Seven Elements expands upon Minecraft&#39;s combat, adding an <em>Elemental</em> alignment to attacks, which applies the corresponding Element onto entities, triggering various <a href="./Elemental_Reactions">Elemental Reactions</a> under certain conditions.</p><p>When an entity receives an instance of damage aligned with the Elements, the corresponding Element is applied onto the target, when possible.</p><p>There are 8 damage types (not to be confused with <a href="https://minecraft.wiki/w/Damage_type" target="_blank" rel="noreferrer">Minecraft/Damage type</a>), which are composed of <a href="./The_Seven_Elements">the Seven Elements</a>: <span class="pyro"><strong>Pyro</strong></span>, <span class="hydro"><strong>Hydro</strong></span>, <span class="anemo"><strong>Anemo</strong></span>, <span class="electro"><strong>Electro</strong></span>, <span class="dendro"><strong>Dendro</strong></span>, <span class="cryo"><strong>Cryo</strong></span>, <span class="geo"><strong>Geo</strong></span>, as well as <strong>Physical</strong>, the non-Element damage type.</p><p>Any instance of damage not aligned with an Element is considered <strong>Physical</strong>.</p><p>There are various ways elements may be applied to entities.</p><h2 id="Elemental_Infusion" tabindex="-1">Elemental Infusion <a class="header-anchor" href="#Elemental_Infusion" aria-label="Permalink to “Elemental Infusion”">​</a></h2><p>When using the <a href="../../Infusion_Table">Infusion Table</a>, an item may be infused with an element.</p><p>When an item is infused with an element, its elemental infusion is appended at the end of its name. It is also given a static glint with the color of its infused element, to indicate it&#39;s been infused with one.</p><p><img src="'+o+'" alt="Tooltip comparison" loading="lazy"></p><p>This infusion has the <strong>highest</strong> priority, and will take effect <strong>first</strong> before succeeding infusion methods given that the damage being dealt does not have an elemental infusion or is dealing <strong>Physical DMG</strong>.</p><p>Depending on the item infused, elemental damage may be dealt in different methods.</p><h3 id="Direct_Elemental_Damage" tabindex="-1">Direct Elemental Damage <a class="header-anchor" href="#Direct_Elemental_Damage" aria-label="Permalink to “Direct Elemental Damage”">​</a></h3><p>For most items and weapons, you <strong>must</strong> deal damage with the infused item to deal elemental damage.</p><p>For example, when you <strong>hit</strong> an entity with an item infused with <span class="hydro"><strong>Hydro</strong></span>, that item will do <span class="hydro"><strong>Hydro DMG</strong></span>.</p><p>Likewise, if you infused an <a href="https://minecraft.wiki/w/End_Crystal" target="_blank" rel="noreferrer">End Crystal</a> with an element, <strong>placed it</strong> and <strong>detonated it</strong>, it will instead deal <span class="pyro"><strong>Pyro DMG</strong></span> (due to <code>minecraft:explosion</code> <a href="#Elemental_Damage_Sources">Elemental Damage Source</a>) instead of the element you infused it with.</p><h3 id="Indirect_Elemental_Damage" tabindex="-1">Indirect Elemental Damage <a class="header-anchor" href="#Indirect_Elemental_Damage" aria-label="Permalink to “Indirect Elemental Damage”">​</a></h3><p>For supported items like the <a href="https://minecraft.wiki/w/Bow" target="_blank" rel="noreferrer">Bow</a>, <a href="https://minecraft.wiki/w/Crossbow" target="_blank" rel="noreferrer">Crossbow</a> and <a href="https://minecraft.wiki/w/Trident" target="_blank" rel="noreferrer">Trident</a>, the shot projectile or thrown Trident will be infused with the element the item is infused with, and will deal elemental damage.</p><p>For infused projectiles loaded into a <a href="https://minecraft.wiki/w/Bow" target="_blank" rel="noreferrer">Bow</a> or <a href="https://minecraft.wiki/w/Crossbow" target="_blank" rel="noreferrer">Crossbow</a> such as <a href="https://minecraft.wiki/w/Arrow" target="_blank" rel="noreferrer">Arrows</a> and <a href="https://minecraft.wiki/w/Firework_Rocket" target="_blank" rel="noreferrer">Firework Rockets</a>, their infusions will apply <strong>only if</strong> the Bow or Crossbow the projectile is loaded into has no existing elemental infusion.</p><p>For non-supported items like the <a href="https://minecraft.wiki/w/Snowball" target="_blank" rel="noreferrer">Snowball</a> and <a href="https://minecraft.wiki/w/Egg" target="_blank" rel="noreferrer">Egg</a>, the shot projectile will <strong>not</strong> be infused with the element the item is infused with. As a result, elemental damage <strong>must</strong> be dealt in the same method as <a href="#Direct_Elemental_Damage">Direct Elemental Damage</a>: hitting the entity with the item itself.</p><h2 id="Elemental_Damage_Sources" tabindex="-1">Elemental Damage Sources <a class="header-anchor" href="#Elemental_Damage_Sources" aria-label="Permalink to “Elemental Damage Sources”">​</a></h2><p>Some damage sources like <code>minecraft:freeze</code> (from <a href="https://minecraft.wiki/w/Powder_Snow#Freezing" target="_blank" rel="noreferrer">Powder Snow&#39;s Freeze DMG</a>), <a href="https://minecraft.wiki/w/Damage#Drowning" target="_blank" rel="noreferrer"><code>minecraft:drown</code></a>, and <a href="https://minecraft.wiki/w/Explosion#Damage" target="_blank" rel="noreferrer"><code>minecraft:explosion</code></a> have innate Elemental infusions tied to them.</p><p>Like <a href="#Mob_Elemental_Damage">Mob Elemental Damage</a>, these elemental damage instances apply <strong>1 <a href="./Elemental_Gauge_Theory">gauge unit</a></strong> of their corresponding Element, given that the element can be an <a href="./Elemental_Gauge_Theory#elemental_auras_and_the_aura_tax">Aura Element</a>.</p><p>This infusion has the <strong>second</strong> highest priority, and will take effect before succeeding infusion methods given that the damage being dealt does not have an elemental infusion or is dealing <strong>Physical DMG</strong>.</p><h2 id="Mob_Elemental_Damage" tabindex="-1">Mob Elemental Damage <a class="header-anchor" href="#Mob_Elemental_Damage" aria-label="Permalink to “Mob Elemental Damage”">​</a></h2><p>Some mobs like the <a href="https://minecraft.wiki/w/Drowned" target="_blank" rel="noreferrer">Drowned</a>, <a href="https://minecraft.wiki/w/Stray" target="_blank" rel="noreferrer">Stray</a>, and the <a href="https://minecraft.wiki/w/Snow_Golem" target="_blank" rel="noreferrer">Snow Golem</a> now deal elemental damage.</p><p>These elemental damage instances apply <strong>1 <a href="./Elemental_Gauge_Theory">gauge unit</a></strong> of their corresponding Element, given that the element can be an <a href="./Elemental_Gauge_Theory#Elemental_Auras_and_the_Aura_Tax">Aura Element</a></p><p>This infusion has the <strong>third</strong> highest priority, and will take effect before succeeding infusion methods given that the damage being dealt does not have an elemental infusion or is dealing <strong>Physical DMG</strong>.</p><h2 id="Natural_Element_Sources" tabindex="-1">Natural Element Sources <a class="header-anchor" href="#Natural_Element_Sources" aria-label="Permalink to “Natural Element Sources”">​</a></h2><p>In Seven Elements, there are also a couple of ways you can be applied with an element <strong>naturally</strong>!</p><p>When in fire, <span class="pyro"><strong>Pyro</strong></span> is applied on you. This is toggled with the <code>seven-elements:pyro_from_fire</code> gamerule.</p><div align="center"><video width="95%" height="auto" controls><source src="'+i+'" type="video/mp4"> Your browser does not support the video tag. </video></div><br><p>When in water, <span class="hydro"><strong>Hydro</strong></span> is applied on you. This is toggled with the <code>seven-elements:hydro_from_water</code> gamerule!</p><div align="center"><video width="95%" height="auto" controls><source src="'+s+'" type="video/mp4"> Your browser does not support the video tag. </video></div><br><p>When struck by lightning, <span class="electro"><strong>Electro</strong></span> is applied on you. This is toggled with the <code>seven-elements:electro_from_thunder</code> gamerule!</p><div align="center"><video width="95%" height="auto" controls><source src="'+l+'" type="video/mp4"> Your browser does not support the video tag. </video></div><h2 id="Implementation" tabindex="-1">Implementation <a class="header-anchor" href="#Implementation" aria-label="Permalink to “Implementation”">​</a></h2><p>The implementation of elements in <strong>Seven Elements</strong> aims to resemble that of Genshin Impact&#39;s while being inherently unique code-wise.</p><p>As much as possible, <strong>Seven Elements</strong> wishes a one-to-one recreation of the Elemental system from Genshin Impact. As such, all elemental <em>quirks</em> from Genshin are expected to work in the same way in <strong>Seven Elements</strong>.</p><p>However, there are <em>some</em> changes upon <em>transposing</em> the Elemental system into Minecraft, ensuring a proper integration with Minecraft rather than a &quot;I made Minecraft into Genshin&quot; experience.</p><h3 id="Cryo_Status" tabindex="-1">Cryo Status <a class="header-anchor" href="#Cryo_Status" aria-label="Permalink to “Cryo Status”">​</a></h3><p>When afflicted with the <span class="cryo"><strong>Cryo</strong></span> element, your Movement Speed and Attack Speed is decreased multiplicatively by 15%, Seven Elements&#39;s <em>translation</em> of Genshin Impact&#39;s &quot;-15% Animation Speed&quot; in Minecraft.</p><p>This effect is <strong>permanent</strong> while the <span class="cryo"><strong>Cryo</strong></span> element exists, and is immediately removed upon being unaffected by <span class="cryo"><strong>Cryo</strong></span>.</p><h3 id="Pyro_DMG_and_Fire-related_effects" tabindex="-1">Pyro DMG and Fire-related effects <a class="header-anchor" href="#Pyro_DMG_and_Fire-related_effects" aria-label="Permalink to “Pyro DMG and Fire-related effects”">​</a></h3><p><a href="https://minecraft.wiki/w/Fire_Resistance" target="_blank" rel="noreferrer">Fire Resistance</a> and <a href="https://minecraft.wiki/w/Fire_Protection" target="_blank" rel="noreferrer">Fire Protection</a> do <strong>not</strong> modify any instance of <span class="pyro"><strong>Pyro DMG</strong></span>, to be fair with the other elemental damage types.</p><p>The amount of <span class="pyro"><strong>Pyro DMG</strong></span> an entity takes with and without <a href="https://minecraft.wiki/w/Fire_Resistance" target="_blank" rel="noreferrer">Fire Resistance</a> and/or <a href="https://minecraft.wiki/w/Fire_Protection" target="_blank" rel="noreferrer">Fire Protection</a> will remain the same. <strong>However</strong>, if the <a href="https://minecraft.wiki/w/Damage_type_tag_(Java_Edition)" target="_blank" rel="noreferrer">damage type <strong>tag</strong></a> is of <code>minecraft:is_fire</code>, <strong>only</strong> then will <a href="https://minecraft.wiki/w/Fire_Resistance" target="_blank" rel="noreferrer">Fire Resistance</a> and/or <a href="https://minecraft.wiki/w/Fire_Protection" target="_blank" rel="noreferrer">Fire Protection</a> affect the damage dealt, even if <span class="pyro"><strong>Pyro DMG</strong></span> is dealt.</p><p><span class="pyro"><strong>Pyro DMG</strong></span> is only <strong>not</strong> modified by <a href="https://minecraft.wiki/w/Fire_Resistance" target="_blank" rel="noreferrer">Fire Resistance</a> and/or <a href="https://minecraft.wiki/w/Fire_Protection" target="_blank" rel="noreferrer">Fire Protection</a> <strong>if</strong> its damage type tag is not of <code>minecraft:is_fire</code>.</p><p>In simpler terms, <span class="pyro"><strong>Pyro DMG</strong></span> works like vanilla Minecraft damage; only modified by <a href="https://minecraft.wiki/w/Fire_Resistance" target="_blank" rel="noreferrer">Fire Resistance</a> and/or <a href="https://minecraft.wiki/w/Fire_Protection" target="_blank" rel="noreferrer">Fire Protection</a> when the <a href="https://minecraft.wiki/w/Damage_type_tag_(Java_Edition)" target="_blank" rel="noreferrer">damage type <strong>tag</strong></a> used is modified by it. Otherwise, it is completely unaffected.</p><p>In addition to this, Pyro-infused projectiles will apply Fire-related effects, such as setting <a href="https://minecraft.wiki/w/Mob" target="_blank" rel="noreferrer">mobs</a> on fire, lighting <a href="https://minecraft.wiki/w/Campfire" target="_blank" rel="noreferrer">campfires</a> and <a href="https://minecraft.wiki/w/TNT" target="_blank" rel="noreferrer">TNT</a>, as well as explode a <a href="https://minecraft.wiki/w/Minecart_with_TNT" target="_blank" rel="noreferrer">Minecart with TNT</a>, like a bow enchanted with <a href="https://minecraft.wiki/w/Flame" target="_blank" rel="noreferrer">Flame</a>. This is toggled with the <code>seven-elements:pyro_does_fire_effects</code> game rule.</p><h3 id="Damage_Type_Tags" tabindex="-1">Damage Type Tags <a class="header-anchor" href="#Damage_Type_Tags" aria-label="Permalink to “Damage Type Tags”">​</a></h3><p><strong>All</strong> DMG dealt from reactions:</p><ul><li>Bypasses Minecraft&#39;s DMG cooldown (<a href="https://minecraft.wiki/w/Damage_type_tag_(Java_Edition)#bypasses_cooldown" target="_blank" rel="noreferrer"><code>#minecraft:bypasses_cooldown</code></a>)</li><li>Bypasses Shields (<a href="https://minecraft.wiki/w/Damage_type_tag_(Java_Edition)#bypasses_shields" target="_blank" rel="noreferrer"><code>#minecraft:bypasses_shields</code></a>)</li><li>Has no impact (<a href="https://minecraft.wiki/w/Damage_type_tag_(Java_Edition)#no_impact" target="_blank" rel="noreferrer"><code>#minecraft:no_impact</code></a>)</li><li>Does no knockback (<a href="https://minecraft.wiki/w/Damage_type_tag_(Java_Edition)#no_knockback" target="_blank" rel="noreferrer"><code>#minecraft:no_knockback</code></a>)</li><li>Doesn&#39;t trigger the DMG cooldown (<a href="../../Damage_type_tag#prevents_cooldown_trigger"><code>#seven-elements:prevents_cooldown_trigger</code></a>)</li></ul><p>Unlike <strong>Genshin Impact</strong>, Transformative Reactions (e.g. Overloaded, Superconduct) may also be affected by Minecraft&#39;s DMG-amplifying effects such as <a href="https://minecraft.wiki/w/Protection" target="_blank" rel="noreferrer">Protection</a>, <a href="https://minecraft.wiki/w/Resistance" target="_blank" rel="noreferrer">Resistance</a>, <a href="https://minecraft.wiki/w/Armor#Damage_reduction" target="_blank" rel="noreferrer">Armor and Armor Toughness</a>, etc.</p><p><strong>Overloaded</strong> and <strong>Burning</strong> are considered &quot;Fire&quot; DMG (<a href="https://minecraft.wiki/w/Damage_type_tag_(Java_Edition)#is_fire" target="_blank" rel="noreferrer"><code>#minecraft:is_fire</code></a>). This means that disabling <code>fireDamage</code> or having the <a href="https://minecraft.wiki/w/Fire_Resistance" target="_blank" rel="noreferrer">Fire Resistance</a> effect will nullify both <strong>Overloaded</strong> and <strong>Burning</strong> DMG. Likewise, the <a href="https://minecraft.wiki/w/Fire_Protection" target="_blank" rel="noreferrer">Fire Protection</a> enchantment also reduces the DMG received from these reactions.</p><p><strong>Overloaded</strong> is also considered an explosion and does &quot;Explosion&quot; DMG (<a href="https://minecraft.wiki/w/Damage_type_tag_(Java_Edition)#is_explosion" target="_blank" rel="noreferrer"><code>#minecraft:is_explosion</code></a>). This means that the <a href="https://minecraft.wiki/w/Blast_Protection" target="_blank" rel="noreferrer">Blast Protection</a> enchantment reduces the DMG received from the <strong>Overloaded</strong> reaction, as well as the knockback you may receive from it.</p><p><strong>Electro-Charged</strong> is considered &quot;Lightning&quot; DMG (<a href="https://minecraft.wiki/w/Damage_type_tag_(Java_Edition)#is_lightning" target="_blank" rel="noreferrer"><code>#minecraft:is_lightning</code></a>). However, this will not &quot;transform&quot; mobs upon being hit (e.g. Villager to Witch), as this Damage type tag only dictates if turtles drop bowls upon being killed, as described by the <a href="https://minecraft.wiki/w/Damage_type_tag_(Java_Edition)#is_lightning:~:text=Used%20to%20make%20turtles%20drop%20bowls%20when%20killed%20by%20lightning." target="_blank" rel="noreferrer">Minecraft Wiki</a>.</p><p><strong>Shatter</strong> is now triggered <strong>if</strong> the target receives <strong>any</strong> form of <span class="geo"><strong>Geo DMG</strong></span> <strong>or</strong> when they are <strong>directly</strong> hit by a <a href="../../Item_tag#heavy_weapon">Heavy Weapon</a>, as no concept of &quot;Blunt Attacks&quot; (a.k.a &quot;Heavy Attacks&quot;) and &quot;Poise&quot; exist in Minecraft, and are not easily addable with respect to other mods.</p><p>Unlike <strong>Genshin Impact</strong>, <span class="dendro"><strong>Dendro DMG</strong></span> originating from the <a href="../../Bloom">Bloom</a> reactions and its derivatives are <strong>not limited</strong> to <strong>2</strong> per <strong>0.5s</strong>. This means that an entity can take multiple amounts of <span class="dendro"><strong>Dendro DMG</strong></span> from Bloom-related reactions in a short timeframe without the other damage instances being ignored.</p>',60)])])}const b=t(h,[["render",m]]);export{u as __pageData,b as default};
